def f(g, mode='bbox'):
    h,w=len(g),len(g[0])
    shp=[(i,j) for i in range(h) for j in range(w) if g[i][j]==1]
    r0=min(p[0] for p in shp); r1=max(p[0] for p in shp); c0=min(p[1] for p in shp); c1=max(p[1] for p in shp)
    o=[row[:] for row in g]
    if mode=='bbox':
        # frame = bbox boundary cells (both shape and zeros) -> 2
        for i in range(r0,r1+1):
            for j in (c0,c1):
                if g[i][j]!=1: o[i][j]=2
        for j in range(c0,c1+1):
            for i in (r0,r1):
                if g[i][j]!=1: o[i][j]=2
    else:
        # full grid: border-connected zeros -> 2
        vis=[[False]*w for _ in range(h)]; q=deque()
        for i in (0,h-1):
            for j in range(w):
                if g[i][j]==0 and not vis[i][j]: vis[i][j]=True;q.append((i,j))
        for j in (0,w-1):
            for i in range(h):
                if g[i][j]==0 and not vis[i][j]: vis[i][j]=True;q.append((i,j))
        while q:
            a,b=q.popleft()
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=a+di,b+dj
                if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not vis[ni][nj]:
                    vis[ni][nj]=True;q.append((ni,nj))
        for i in range(h):
            for j in range(w):
                if g[i][j]==0 and vis[i][j]: o[i][j]=2
    # enclosed zero components: fill 3 iff >=2 shape neighbors (4-dir)
    for c in comps(o,0):
        nb1=sum(1 for (a,b) in c for ni,nj in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)) if 0<=ni<h and 0<=nj<w and g[ni][nj]==1)
        o2=c[0]; 
        if nb1>=2:
            for (a,b) in c: o[a][b]=3
    return o
