import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import deque
# New idea: flood fill from border over zeros ONLY (4-dir). Reached zeros -> 2; unreached zeros -> 3? check.
def f(g):
    h,w=len(g),len(g[0])
    vis=[[False]*w for _ in range(h)]; q=deque()
    for i_ in range(h):
        for j_ in range(w):
            if g[i_][j_]==0 and (i_==0 or i_==h-1 or j_==0 or j_==w-1) and not vis[i_][j_]:
                vis[i_][j_]=True; q.append((i_,j_))
    while q:
        a,b=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=a+di,b+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not vis[ni][nj]:
                vis[ni][nj]=True; q.append((ni,nj))
    out=[row[:] for row in g]
    for i_ in range(h):
        for j_ in range(w):
            if g[i_][j_]==0:
                out[i_][j_]=3 if vis[i_][j_] else 2
    return out
